check('multichunk Unicode and newline JSON roundtrip bounded async char buffer',()=>{const m=model();const q=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{text:'汉😀'.repeat(1000)}});q.ctx.Request.InputStream.body=JSON.stringify(q.msg,null,2);q.ctx.Request.ContentLength64=BigInt(Buffer.byteLength(q.ctx.Request.InputStream.body));m.many(30);assert(q.out.ok);assert.equal(m.counts().sets,1);assert.equal(m.counts().saves,1);});
check('queue32 bound enforced while long publish active',()=>{const m=model({publishDelay:10000});const p=m.request('publish',{pkg:'Gesture'},{deadlineMs:1792145120000});m.many(3);const qs=[];for(let i=0;i<36;i++)qs.push(m.request('project_info'));m.many(45);assert(m.context.Bridge.queue.length<=32);assert(qs.some(q=>q.out&&q.out.error&&q.out.error.code==='QUEUE_FULL'));assert.equal(m.counts().publishes,1);});
check('evicted completion payload retains tombstone without replay',()=>{const m=model();const first=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{text:'only-once'}});m.many();for(let i=0;i<65;i++){m.request('project_info');m.many(4);}const duplicate=m.request(first.msg.cmd,first.msg.args,{requestId:first.msg.requestId,expectedRevision:first.msg.expectedRevision});m.many();assert.equal(duplicate.out.error.code,'COMPLETION_RETAINED_NO_REPLAY');assert.equal(m.counts().sets,1);});
check('queued deadline expires before handler execution',()=>{const m=model({publishDelay:10000});m.request('publish',{pkg:'Gesture'},{deadlineMs:1792145120000});m.many(3);const q=m.request('save_all',{}, {deadlineMs:1792145000600});m.many(10);m.context.Bridge.current.done=true;m.many(10);assert.equal(q.out.error.code,'DEADLINE_EXCEEDED');assert.equal(m.counts().saves,0);});
check('screenshot rejects escape and returns asynchronous-not-verified marker',()=>{const m=model();const bad=m.request('screenshot',{path:'C:/outside.png'});m.many();assert(!bad.out.ok);const good=m.request('screenshot',{});m.many();assert(good.out.ok);assert.equal(good.out.data.verified,false);assert(good.out.data.screenshot.startsWith(m.config.screenshotDir));});
check('malformed JSON request does not poison pump',()=>{const m=model();const bad=m.request('ping',{}, {},{body:'{not json'});m.many();assert.equal(bad.out.error.code,'INVALID_JSON');const good=m.request('ping');m.many();assert(good.out.ok);});
check('fixed ContentLength equals actual UTF8 LF body; no normal stream Close',()=>{const m=model();const q=m.request('ping');m.many();assert(q.out.ok);assert.equal(q.ctx.Response.ContentLength64,BigInt(Buffer.byteLength(q.ctx.Response.OutputStream.body)));assert.equal(q.ctx.Response.SendChunked,false);assert.equal(q.ctx.Response.aborted,true);assert.equal(m.counts().normalStreamCloses,0);});
check('early rejection without reading body force-aborts only after complete fixed-length reply',()=>{const m=model();const q=m.request('ping',{}, {},{headers:{authorization:'Bearer invalid'},slow:true});m.many();assert.equal(q.out.error.code,'UNAUTHORIZED');assert.equal(q.ctx.Response.aborted,true);assert.equal(q.ctx.Response.ContentLength64,BigInt(Buffer.byteLength(q.ctx.Response.OutputStream.body)));assert.equal(m.counts().normalStreamCloses,0);const next=m.request('ping');m.many();assert(next.out.ok);});
check('Timers pumps independently when App callback absent; frame dedup prevents duplicate work',()=>{const m=model({appPaused:true});const q=m.request('ping');m.many(20);assert(q.out.ok);assert.equal(m.context.Bridge.appEntries,0);assert.equal(m.context.Bridge.timerEntries,20);assert.equal(m.context.Bridge.frame,20);const both=model();both.many(20);assert.equal(both.context.Bridge.appEntries,20);assert.equal(both.context.Bridge.timerEntries,20);assert.equal(both.context.Bridge.frame,20);});
check('destroy unregisters both sources; diagnostic counters emitted at10s interval',()=>{const m=model();m.many(120,100);const counters=m.diag().filter(x=>x.code==='PUMP_COUNTERS');assert.equal(counters.length,2);assert(counters[1].detail.appEntries>0);assert(counters[1].detail.timerEntries>0);m.context.exports.onDestroy();assert.equal(m.timer.callback,null);assert.equal(m.app.callback,null);});
check('one lifecycle hold protects host publish background balance; destroy releases once',()=>{const m=model();assert.equal(m.counts().startJobs,1);assert.equal(m.counts().hostBackgroundJobs,1);m.app.StartBackgroundJob();m.app.EndBackgroundJob();assert.equal(m.counts().hostBackgroundJobs,1);assert(m.application.runInBackground);m.context.exports.onDestroy();m.context.exports.onDestroy();assert.equal(m.counts().endJobs,2);assert.equal(m.counts().startJobs,2);assert.equal(m.counts().hostBackgroundJobs,0);});
check('ping background effective is real getter not cached boot flag',()=>{const m=model();m.application.runInBackground=false;const q=m.request('ping');m.many();assert.equal(q.out.data.backgroundPolicy.effective,false);assert.equal(q.out.data.backgroundPolicy.holdActive,true);assert.equal(q.out.data.backgroundPolicy.fallback,false);});
check('missing hold API uses explicit weak setter fallback and never calls End',()=>{const m=model({holdBindingFail:true});assert.equal(m.counts().startJobs,0);m.application.runInBackground=false;const q=m.request('ping');m.many();assert(q.out.data.backgroundPolicy.effective);assert.equal(q.out.data.backgroundPolicy.holdActive,false);assert.equal(q.out.data.backgroundPolicy.fallback,true);m.context.exports.onDestroy();assert.equal(m.counts().endJobs,0);assert.equal(m.application.runInBackground,false);});
check('xy/size apply native scalars first, preserve fractional Number values, no extension false-success',()=>{const m=model({silentVectorExtension:true});const q=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{xy:'12.5,-34.25',size:'88.75,99.125'}});m.many();assert(q.out.ok);assert.equal(m.label.x,12.5);assert.equal(m.label.y,-34.25);assert.equal(m.label.width,88.75);assert.equal(m.label.height,99.125);assert.equal(m.counts().extensionSets,0);assert.deepEqual(q.out.data.applied,['xy:x/y','size:width/height']);});
check('vector dimension/range validation rejects before mutation',()=>{const m=model();const values=[{size:'-1,2'},{xy:'1,2,3'},{xy:'NaN,1'},{xy:'1000001,1'}];const qs=values.map(props=>m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props}));m.many();for(const q of qs)assert.equal(q.out.error.code,'INVALID_ARGUMENTS');assert.equal(m.counts().sets,0);});
check('vector readback mismatch fails without extension retry or false saved result',()=>{const m=model({scalarReadbackFails:true});const q=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{xy:'1.5,2.5'}});m.many();assert(!q.out.ok);assert.equal(q.out.error.code,'PROPERTY_READBACK_MISMATCH');assert.equal(m.counts().extensionSets,0);assert.equal(m.counts().sets,2);assert.equal(m.counts().saves,0);});
check('custom configured port starts and authenticates',()=>{const m=model({port:18123});assert.equal(m.listeners[0].prefix,'http://127.0.0.1:18123/');const q=m.request('ping');m.many();assert(q.out.ok);});
check('invalid port rejected before listener starts',()=>{const m=model({port:0});assert.equal(m.listeners.length,0);assert(m.diag().some(x=>x.code==='CONFIG_LOAD_FAILED'));});

check('native authority rejects two writers with same revision',()=>{const m=model();const a=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{text:'writer-a'}},{expectedRevision:0});const b=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{text:'writer-b'}},{expectedRevision:0});m.many(30);assert(a.out.ok);assert.equal(b.out.error.code,'REVISION_CONFLICT');assert.equal(m.label.text,'writer-a');assert.equal(m.counts().sets,1);assert.equal(a.out.revision,1);});
check('mutation without revision rejected before work',()=>{const m=model();const q=m.request('save_all',{}, {expectedRevision:undefined});m.many();assert.equal(q.out.error.code,'REVISION_REQUIRED');assert.equal(m.counts().saves,0);});
check('failed mutation invalidates stale readers',()=>{const m=model({scalarReadbackFails:true});const q=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{xy:'1,2'}});m.many();assert(!q.out.ok);assert.equal(m.context.Coordination.revision,1);const stale=m.request('save_all',{}, {expectedRevision:0});m.many();assert.equal(stale.out.error.code,'REVISION_CONFLICT');});
check('refresh rejects unsaved documents before native refresh',()=>{const m=model();m.request('list_children',{pkg:'Gesture',name:'Main'});m.many();m.app.docView.FindDocument().isModified=true;const q=m.request('refresh');m.many();assert.equal(q.out.error.code,'UNSAVED_DOCUMENTS');assert.equal(m.counts().refreshes,0);});
check('large traversal returns every item exactly once in bounded pages',()=>{const m=model();const items=Array.from({length:5000},(_,i)=>({id:'bulk'+i,name:'Bulk'+i,type:3,path:'/',width:1,height:1,children:null}));m.pkg.rootItem.children={Count:items.length,get_Item:i=>items[i]};let cursor,ids=[],pages=0;do{const q=m.request('list_items_page',{pkg:'Gesture',limit:100,...(cursor?{cursor}: {})});m.many();assert(q.out.ok);assert(q.out.data.items.length<=100);assert(Buffer.byteLength(JSON.stringify(q.out))<65536);ids.push(...q.out.data.items.map(x=>x.id));cursor=q.out.data.nextCursor;assert(++pages<60);}while(cursor);assert.equal(ids.length,5001);assert.equal(new Set(ids).size,5001);});
check('consumed cursor cannot silently skip records',()=>{const m=model();const first=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();const cursor=first.out.data.nextCursor;const next=m.request('list_items_page',{pkg:'Gesture',limit:1,cursor});m.many();assert(next.out.ok);const again=m.request('list_items_page',{pkg:'Gesture',limit:1,cursor});m.many();assert.equal(again.out.error.code,'CURSOR_EXPIRED');});
check('write invalidates pending pagination cursor',()=>{const m=model();const page=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();const save=m.request('save_all');m.many();assert(save.out.ok);const next=m.request('list_items_page',{pkg:'Gesture',cursor:page.out.data.nextCursor});m.many();assert.equal(next.out.error.code,'CURSOR_EXPIRED');});
check('external structural change detected on pending ancestor',()=>{const m=model();const page=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();m.pkg.rootItem.children={Count:2,get_Item:i=>null};const next=m.request('list_items_page',{pkg:'Gesture',cursor:page.out.data.nextCursor});m.many();assert.equal(next.out.error.code,'CURSOR_CHANGED');});
check('cursor TTL expires and capacity bounded',()=>{const m=model();for(let i=0;i<16;i++){const p=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many(4);assert(p.out.ok);}const over=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();assert.equal(over.out.error.code,'CURSOR_CAPACITY');m.many(1,61000);const fresh=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();assert(fresh.out.ok);});
check('UTF8 byte budget ends page before response bound',()=>{const m=model();const items=Array.from({length:20},(_,i)=>({id:'b'+i,name:'汉'.repeat(2000),type:3,path:'/',width:1,height:1,children:null}));m.pkg.rootItem.children={Count:items.length,get_Item:i=>items[i]};const p=m.request('list_items_page',{pkg:'Gesture',limit:100});m.many();assert(p.out.ok);assert(p.out.data.items.length<20);assert(p.out.data.nextCursor);assert(Buffer.byteLength(JSON.stringify(p.out))<65536);});

check('controller create waits for document and reads native IDs',()=>{const m=model();const q=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle','Run'],exported:false});m.many();assert(q.out.ok,JSON.stringify(q.out));assert.deepEqual(q.out.data.pages,[{id:'p0',name:'Idle'},{id:'p1',name:'Run'}]);assert.equal(m.counts().saves,1);assert.equal(q.out.revision,1);});
check('controller CRUD preserves IDs and opaque native actions',()=>{const m=model();m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle','Run']});m.many();const q=m.request('controller_update',{pkg:'Gesture',name:'Main',controller:'State',newName:'Mode',pageNames:[{id:'p1',name:'Active'}],exported:true});m.many();assert(q.out.ok);assert.deepEqual(q.out.data.pages,[{id:'p0',name:'Idle'},{id:'p1',name:'Active'}]);assert.deepEqual(m.app.docView.FindDocument().content.GetController('Mode').actions,[{opaque:true}]);const sw=m.request('controller_select',{pkg:'Gesture',name:'Main',controller:'Mode',index:1});m.many();assert(sw.out.ok);assert.equal(sw.out.data.previousIndex,0);assert.equal(sw.out.data.selectedIndex,1);const rm=m.request('controller_remove',{pkg:'Gesture',name:'Main',controller:'Mode'});m.many();assert(rm.out.ok);const list=m.request('controller_list',{pkg:'Gesture',name:'Main'});m.many();assert.deepEqual(list.out.data.controllers,[]);});
check('controller invalid args rejected before opening or saving',()=>{for(const args of [{pages:[]},{pages:['a','a']},{pages:['a,b']},{pages:['a'],exported:1},{pages:['\ud800']},{pages:Array(101).fill('a')}]){const m=model(),q=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',...args});m.many();assert.equal(q.out.error.code,'INVALID_ARGUMENTS');assert.equal(m.counts().opens,0);assert.equal(m.counts().saves,0);}});
check('controller unknown page or duplicate resulting names never mutates original',()=>{const m=model();m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle','Run']});m.many();for(const pageNames of [[{id:'unknown',name:'X'}],[{id:'p1',name:'Idle'}]]){const q=m.request('controller_update',{pkg:'Gesture',name:'Main',controller:'State',pageNames});m.many();assert(!q.out.ok);assert.equal(m.app.docView.FindDocument().content.GetController('State').GetPages().get_Item(1).name,'Run');}assert.equal(m.counts().saves,1);});
check('controller dirty doc rejected without saving unrelated work',()=>{const m=model();m.request('list_children',{pkg:'Gesture',name:'Main'});m.many();m.app.docView.FindDocument().isModified=true;const q=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle']});m.many();assert.equal(q.out.error.code,'UNSAVED_DOCUMENT');assert.equal(m.counts().saves,0);});
check('controller missing native capability is explicit before mutation',()=>{const m=model();m.request('list_children',{pkg:'Gesture',name:'Main'});m.many();m.app.docView.FindDocument().AddController=undefined;const q=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle']});m.many();assert.equal(q.out.error.code,'CAPABILITY_UNSUPPORTED');assert.equal(m.counts().saves,0);});
check('controller simultaneous stale writers are rejected',()=>{const m=model();const a=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'First',pages:['Idle']},{expectedRevision:0});const b=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'Second',pages:['Idle']},{expectedRevision:0});m.many(30);assert(a.out.ok);assert.equal(b.out.error.code,'REVISION_CONFLICT');assert.equal(m.app.docView.FindDocument().content.controllers.Count,1);});

check('restored inactive document is explicitly opened before waiting',()=>{const m=model();const original=m.app.docView.FindDocument;let first=true;m.app.docView.FindDocument=()=>first?(first=false,{content:null}):original();const q=m.request('set_property',{pkg:'Gesture',name:'Main',target:'n1',props:{text:'loaded'}});m.many();assert(q.out.ok);assert.equal(m.label.text,'loaded');assert.equal(m.counts().opens,1);});
check('pagination preserves native string resource types',()=>{const m=model();m.pkg.rootItem.type='folder';const q=m.request('list_items_page',{pkg:'Gesture',limit:1});m.many();assert(q.out.ok);assert.equal(q.out.data.items[0].type,'folder');});

check('controller failed native save does not report success',()=>{const m=model({saveFailure:true});const q=m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle']});m.many();assert.equal(q.out.error.code,'SAVE_NOT_CONFIRMED');assert(m.app.docView.FindDocument().isModified);});
check('controller oversized preexisting state rejected before switch',()=>{const m=model();m.request('controller_create',{pkg:'Gesture',name:'Main',controller:'State',pages:['Idle']});m.many();const c=m.app.docView.FindDocument().content.GetController('State');for(let i=0;i<100;i++)c.AddPage('p'+i);const q=m.request('controller_select',{pkg:'Gesture',name:'Main',controller:'State',index:1});m.many();assert.equal(q.out.error.code,'RESULT_LIMIT');assert.equal(c.selectedIndex,0);assert.equal(m.counts().saves,1);});
check('controller list paginates native rows without dropping names',()=>{const m=model();m.request('list_children',{pkg:'Gesture',name:'Main'});m.many();const doc=m.app.docView.FindDocument();for(let i=0;i<25;i++)doc.AddController({name:'C'+i,pages:[{id:'p0',name:'Idle'}],selectedIndex:0,exported:false});let offset=0,names=[];do{const q=m.request('controller_list',{pkg:'Gesture',name:'Main',offset,limit:7});m.many();assert(q.out.ok);assert(q.out.data.controllers.length<=7);names.push(...q.out.data.controllers.map(c=>c.name));offset=q.out.data.nextOffset;}while(offset!==null);assert.equal(new Set(names).size,25);});

check('relation uses editor enums and Size expands before native save',()=>{const m=model();const q=m.request('relation_set',{pkg:'Gesture',name:'Main',objectId:'n1',targetId:'$parent',definitions:[{type:'Size',percent:false}]});m.many();assert(q.out.ok,JSON.stringify(q.out));assert.deepEqual(q.out.data.relation.definitions,[{type:'Width',percent:false},{type:'Height',percent:false}]);assert.deepEqual(m.label.relations.GetItem(m.label.parent).values.map(x=>x.type),[11,23]);assert.equal(m.counts().saves,1);});
check('relation replacement preserves other targets and removal is target scoped',()=>{const m=model();const base={pkg:'Gesture',name:'Main',objectId:'n1'};for(const [targetId,type]of [['$parent','Width'],['n0','Left_Left']]){const q=m.request('relation_set',{...base,targetId,definitions:[{type}]});m.many();assert(q.out.ok);}let q=m.request('relation_set',{...base,targetId:'$parent',definitions:[{type:'Height',percent:true}]});m.many();assert(q.out.ok);assert.equal(m.label.relations.items.Count,2);q=m.request('relation_remove',{...base,targetId:'n0'});m.many();assert(q.out.ok);assert.equal(m.label.relations.items.Count,1);assert.equal(m.label.relations.items.get_Item(0).values[0].type,23);});
check('relation invalid definitions rejected before document open',()=>{for(const definitions of [[],[{type:'Script'}],[{type:'Width',percent:1}],[{type:'Size'},{type:'Width'}],[{type:'Height'},{type:'Height'}]]){const m=model(),q=m.request('relation_set',{pkg:'Gesture',name:'Main',objectId:'n1',targetId:'$parent',definitions});m.many();assert.equal(q.out.error.code,'INVALID_ARGUMENTS');assert.equal(m.counts().opens,0);}});
check('relation self and indirect cycles rejected',()=>{const m=model(),base={pkg:'Gesture',name:'Main',objectId:'n1'};let q=m.request('relation_set',{...base,targetId:'n1',definitions:[{type:'Width'}]});m.many();assert.equal(q.out.error.code,'RELATION_SELF');q=m.request('relation_set',{...base,targetId:'n0',definitions:[{type:'Left_Left'}]});m.many();assert(q.out.ok);q=m.request('relation_set',{...base,objectId:'n0',targetId:'n1',definitions:[{type:'Left_Left'}]});m.many();assert.equal(q.out.error.code,'RELATION_CYCLE');assert.equal(m.counts().saves,1);});
check('relation dirty disabled and inherited guards precede mutation',()=>{for(const mode of ['dirty','disabled','readonly']){const m=model();m.request('list_children',{pkg:'Gesture',name:'Main'});m.many();const doc=m.app.docView.FindDocument();if(mode==='dirty')doc.isModified=true;if(mode==='disabled')m.label.docElement.relationsDisabled=true;if(mode==='readonly'){m.label.relations.add(m.label.parent,'[]');m.label.relations.GetItem(m.label.parent).readOnly=true;}const q=m.request('relation_set',{pkg:'Gesture',name:'Main',objectId:'n1',targetId:'$parent',definitions:[{type:'Width'}]});m.many();assert.equal(q.out.error.code,{dirty:'UNSAVED_DOCUMENT',disabled:'RELATIONS_DISABLED',readonly:'RELATION_READ_ONLY'}[mode]);assert.equal(m.counts().saves,0);}});
check('relation save failure visible and revision claimed',()=>{const m=model({saveFailure:true});const q=m.request('relation_set',{pkg:'Gesture',name:'Main',objectId:'n1',targetId:'$parent',definitions:[{type:'Width'}]});m.many();assert.equal(q.out.error.code,'SAVE_NOT_CONFIRMED');assert.equal(q.out.revision,1);});
check('relation clients stale revisions conflict',()=>{const m=model(),args={pkg:'Gesture',name:'Main',objectId:'n1',targetId:'$parent',definitions:[{type:'Width'}]};const a=m.request('relation_set',args,{expectedRevision:0}),b=m.request('relation_set',args,{expectedRevision:0});m.many(30);assert(a.out.ok);assert.equal(b.out.error.code,'REVISION_CONFLICT');});


function transRequest(m,cmd,args={}){const q=m.request(cmd,{pkg:'Gesture',name:'Main',transition:'Move',...args});m.many();return q.out;}
function transCreate(m){const r=transRequest(m,'transition_create');assert(r.ok,JSON.stringify(r));return m.app.docView.FindDocument();}
function transKey(m,frame,values,tween=false){return transRequest(m,'transition_keyframe_set',{targetId:'n1',type:'XY',frame,values,tween});}
check('transition named creation uses no-arg native creation then property facade',()=>{const m=model();transCreate(m);assert.equal(m.app.docView.FindDocument().content.transitions.GetItem('Move').name,'Move');assert.equal(m.counts().saves,1);assert.equal(transRequest(m,'transition_create').error.code,'TRANSITION_EXISTS');});
check('transition CRUD updates only selected native timeline and exits',()=>{const m=model(),doc=transCreate(m);transRequest(m,'transition_create',{transition:'Keep'});assert(transRequest(m,'transition_update',{settings:{frameRate:30,autoPlay:false,autoPlayRepeat:2}}).ok);assert.equal(doc.content.transitions.GetItem('Move').frameRate,30);assert.equal(doc.content.transitions.GetItem('Keep').frameRate,24);assert(!doc.timelineMode);assert(transRequest(m,'transition_remove').ok);assert(doc.content.transitions.GetItem('Keep'));});
check('transition keyframe upsert preserves tuple identity without CreateItem double-add',()=>{const m=model();transCreate(m);assert(transKey(m,30,[100,200]).ok);assert(transKey(m,0,[10,20],true).ok);assert(transKey(m,30,[300,400]).ok);const r=transRequest(m,'transition_list');assert.equal(r.data.total,2);assert.deepEqual(r.data.items.map(x=>x.frame),[0,30]);assert.equal(r.data.items[1].value,'300,400');assert(transRequest(m,'transition_keyframe_remove',{targetId:'n1',type:'XY',frame:0}).ok);assert.equal(transRequest(m,'transition_list').data.total,1);});
check('transition rejects missing tween endpoint or endpoint deletion before native update',()=>{const m=model(),doc=transCreate(m);assert.equal(transKey(m,0,[1,2],true).error.code,'TWEEN_ENDPOINT_REQUIRED');assert.equal(doc.content.transitions.GetItem('Move').items.Count,0);transKey(m,30,[30,40]);transKey(m,0,[1,2],true);const n=m.counts().saves;assert.equal(transRequest(m,'transition_keyframe_remove',{targetId:'n1',type:'XY',frame:30}).error.code,'TWEEN_ENDPOINT_REQUIRED');assert.equal(m.counts().saves,n);assert(!doc.timelineMode);});
check('transition argument guards run before document open',()=>{for(const args of [{values:[1]},{values:[1,Infinity]},{type:'Sound'},{frame:-1},{tween:1},{label:'bad,name'}]){const m=model(),r=transRequest(m,'transition_keyframe_set',{targetId:'n1',type:'XY',frame:0,values:[1,2],...args});assert.equal(r.error.code,'INVALID_ARGUMENTS');assert.equal(m.counts().opens,0);}});
check('transition dirty document and active timeline are not overwritten',()=>{for(const mode of ['dirty','timeline']){const m=model(),doc=transCreate(m);if(mode==='dirty')doc.isModified=true;else doc.timelineMode=true;const n=m.counts().saves,r=transRequest(m,'transition_update',{settings:{frameRate:30}});assert.equal(r.error.code,mode==='dirty'?'UNSAVED_DOCUMENT':'TIMELINE_ACTIVE');assert.equal(m.counts().saves,n);}});
check('transition opaque actions paths and custom eases reject before timeline',()=>{for(const kind of ['sound','path','ease']){const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);const key=doc.content.transitions.GetItem('Move').items.get_Item(0);if(kind==='sound')key.type='Sound';else if(kind==='path')key.usePath=true;else key.customEaseData='curve';const n=m.counts().saves;assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'TRANSITION_COMPLEX_UNSUPPORTED');assert.equal(m.counts().saves,n);assert(!doc.timelineMode);}});
check('transition existing dangling target rejected to prevent saving silent deletion',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);doc.content.transitions.GetItem('Move').items.get_Item(0).targetId='missing';assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'TRANSITION_TARGET_INVALID');});
check('transition existing partial/nonfinite values rejected before preview',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);doc.content.transitions.GetItem('Move').items.get_Item(0).encodedValue='-,2';assert.equal(transRequest(m,'transition_sample',{frame:0,targetIds:['n1']}).error.code,'TRANSITION_VALUE_UNSUPPORTED');assert(!doc.timelineMode);});
check('transition clone-loss guard compares against original not only mutated draft',()=>{const m=model({cloneLoss:true}),doc=transCreate(m),t=doc.content.transitions.GetItem('Move');t.CreateItem('n1','XY',0).encodedValue='1,2';const n=m.counts().saves;assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'TRANSITION_CLONE_LOSS');assert.equal(m.counts().saves,n);assert(!doc.timelineMode);});
check('transition missing native timeline identity fails and exits without save',()=>{const m=model(),doc=transCreate(m);doc.EnterTimelineMode=function(){this.timelineMode=true;this.editingTransition={name:'other'};};assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'TIMELINE_CONTEXT');assert(!doc.timelineMode);assert.equal(m.counts().saves,1);});
check('transition native update exception exits own timeline and reports failure',()=>{const m=model(),doc=transCreate(m);doc.UpdateTransition=()=>{throw Error('native failed');};assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'EDITOR_API_ERROR');assert(!doc.timelineMode);assert.equal(m.counts().saves,1);});
check('transition failed native save never reports success',()=>{const m=model({saveFailure:true});assert.equal(transRequest(m,'transition_create').error.code,'SAVE_NOT_CONFIRMED');});
check('transition list paginates keyframes with bounded bytes',()=>{const m=model();transCreate(m);for(let i=0;i<3;i++)assert(transKey(m,i,[i,i]).ok);let r=transRequest(m,'transition_list',{limit:1});assert.equal(r.data.items.length,1);assert.equal(r.data.nextOffset,1);r=transRequest(m,'transition_list',{limit:2,offset:1});assert.equal(r.data.items.length,2);assert.equal(r.data.nextOffset,null);});
check('transition concurrent native revisions allow one mutation',()=>{const m=model(),args={pkg:'Gesture',name:'Main',transition:'Move'};const a=m.request('transition_create',args,{expectedRevision:0}),b=m.request('transition_create',{...args,transition:'Other'},{expectedRevision:0});m.many(30);assert(a.out.ok);assert.equal(b.out.error.code,'REVISION_CONFLICT');});
check('transition numeric preview samples then stops restores all geometry without save',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);transKey(m,30,[100,200]);const n=m.counts().saves,before=[m.label.x,m.label.y];const r=transRequest(m,'transition_sample',{frame:30,targetIds:['n1','n0']});assert(r.ok,JSON.stringify(r));assert.equal(r.data.samples[0].x,100);assert(r.data.checkedStateRestored);assert.deepEqual([m.label.x,m.label.y],before);assert(!doc.timelineMode);assert(!doc.content.transitions.GetItem('Move').playing);assert.equal(m.counts().saves,n);});
check('transition preview and stop exceptions still exit timeline restore geometry',()=>{for(const option of ['previewThrows','stopThrows']){const m=model({[option]:true}),doc=transCreate(m);transKey(m,0,[1,2]);const before=[m.label.x,m.label.y],r=transRequest(m,'transition_sample',{frame:0,targetIds:['n1']});assert.equal(r.error.code,option==='stopThrows'?'TRANSITION_RESTORE_FAILED':'EDITOR_API_ERROR');assert(!doc.timelineMode);assert.deepEqual([m.label.x,m.label.y],before);}});
check('transition preview detects residual gear locks and reports restore failure',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);const old=doc.ExitTimelineMode;doc.ExitTimelineMode=function(){old.call(this);m.label._gearLocked=true;};assert.equal(transRequest(m,'transition_sample',{frame:0,targetIds:['n1']}).error.code,'TRANSITION_RESTORE_FAILED');});
check('transition preview target duplicates and oversize rejected before open',()=>{for(const targetIds of [['n1','n1'],Array(21).fill('n1'),[]]){const m=model();assert.equal(transRequest(m,'transition_sample',{frame:0,targetIds}).error.code,'INVALID_ARGUMENTS');assert.equal(m.counts().opens,0);}});

check('transition sampling rejects duplicate and orphan tracks before Play',()=>{for(const kind of ['duplicate','orphan']){const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);const t=doc.content.transitions.GetItem('Move');if(kind==='duplicate')t.keys.push({...t.keys[0]});else t.keys[0].tween=true;const r=transRequest(m,'transition_sample',{frame:0,targetIds:['n1']});assert.equal(r.error.code,kind==='duplicate'?'KEYFRAME_DUPLICATE':'TWEEN_ENDPOINT_REQUIRED');assert(!doc.timelineMode);assert(!t.playing);}});
check('transition failed Play with residual lock is reported as restore failure',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);const t=doc.content.transitions.GetItem('Move'),exit=doc.ExitTimelineMode;t.Play=()=>{throw Error('play failed');};doc.ExitTimelineMode=function(){exit.call(this);m.label._gearLocked=true;};assert.equal(transRequest(m,'transition_sample',{frame:0,targetIds:['n1']}).error.code,'TRANSITION_RESTORE_FAILED');});
check('transition preview snapshot bound rejects before timeline entry',()=>{const m=model(),doc=transCreate(m);transKey(m,0,[1,2]);doc.content.children={Count:2001};assert.equal(transRequest(m,'transition_sample',{frame:0,targetIds:['n1']}).error.code,'RESULT_LIMIT');assert(!doc.timelineMode);});
check('transition oversized keyframe edits rejected without save',()=>{const m=model(),doc=transCreate(m),t=doc.content.transitions.GetItem('Move');for(let i=0;i<1001;i++)t.CreateItem('n1','XY',i).encodedValue='1,2';const before=m.counts().saves;assert.equal(transRequest(m,'transition_update',{settings:{frameRate:30}}).error.code,'RESULT_LIMIT');assert.equal(m.counts().saves,before);});
